/**
 * Reading Passages — NCERT/CBSE aligned, 30+ per level with appropriate length & difficulty.
 *
 * Difficulty escalates by level:
 * - Basic (Classes 1-4): 1-2 short paragraphs, 2 simple recall questions
 * - Intermediate (Classes 5-7): 2-3 full paragraphs, 3 questions mixing recall + inference
 * - Advanced (Classes 8-10): 3-5 dense paragraphs, 3-4 inference + analysis questions
 */
export type Level = 'basic' | 'intermediate' | 'advanced';

export interface ReadingQuestion {
  text: string;
  options: string[];
  correct: number;
}

export interface ReadingPassage {
  id: number;
  title: string;
  text: string;
  questions: ReadingQuestion[];
}

/** Pick N random items from an array (no repeats). */
export function pickRandom<T>(arr: T[], n: number): T[] {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a.slice(0, Math.min(n, a.length));
}

